package santa

// Authored eval vectors for sigma-rust's santa-probe-method-signatures-2 (2026-11-15, the follow-up to the
// method_type_variable_names families; fork PR 96, branch fork/fix/method-signatures). Measured first in
// santa.spike.MethodSignatures2Probe (local): all 457 selected rows as read, value and cost.
//
// THE RULE, read in 6.0.7: the name rule of the first request (two type variables unify only when their NAMES are
// equal, `unifyTypes`, sigma/ast/package.scala:39-42) reaches trees that write NO type variable. A call whose
// receiver and arguments are all concrete can still fail to unify with its method's domain: an item of another
// type (`Coll(3,1,2).updated(0, 1L)`), a receiver of another kind (`7.reverse`), a tuple against `Coll` (`IV` binds
// to `Any`, then conflicts), too few arguments below tree v3. `specializeFor` (SMethod.scala:193-199) then returns
// the method as it is, and the call's static type is the range with the method TABLE's variable in it: `Coll[IV]`
// on the JVM. The next generic call meets that name and unifies `IV` with `IV` and nothing else. So an
// implementation whose tables use other names differs on trees with only concrete types, for calls of ANY generic
// method over such a receiver or argument (map, flatMap, getOrElse, filter, append, apply, slice, Option.get…),
// both ways, at parse and at evaluation.
//
// THE SHAPE (sigma-rust's generators): the inner call that does not specialise sits in an untaken branch,
// `if (false) <inner> else <real value>`, so the outer call evaluates over a real value and gets the inner call's
// static type; an outer call around it; a consumer around that (`serialize`, `== value`, `+ 1`). rows-nested: no
// type variable anywhere in the bytes; rows-nested2: the same outer calls over script-typed inner calls;
// rows-concrete: tuple, `Coll[Any]` and too-few-arguments receivers.
// PARSE TWINS, added here: every selected row the JVM errors on also appears wrapped as
// `if (true) true else { val v = <expr>; false }`, true where the JVM parses it (and throws only at evaluation),
// errored where it refuses it at parse: the eval tier grades the two alike on the bare row.
// CONTROLS, derived here: the same outer call and consumer over the real value directly (the untaken If replaced by
// its else branch, read by the reader), deduplicated, kept only where they evaluate (an outer call with no eval
// method as a method call, `append`/`slice`/`Option.getOrElse`, throws over any receiver: no control there).
//
// One family, MethodCall.unspecialised_call_names_v6 (activated 3, tree v3).

import io.circe.Json
import scorex.util.encode.Base16
import sigma.serialization.SigmaSerializer

object AuthoredEvalUnspecialisedCallNames {
  val Source = "santa:authored-unspecialised-call-names"
  val Stamp = "jvm:sigma-state-6.0.7"
  val Op = "MethodCall.unspecialised_call_names_v6"
  val IntInput: Json = Json.obj("kind" -> Json.fromString("Int"), "value" -> Json.fromInt(0))
  private def hx(bs: Array[Byte]): String = Base16.encode(bs).toLowerCase
  private def vlq(n: Int): String = { val w = SigmaSerializer.startWriter(); w.putUInt(n.toLong); hx(w.toBytes) }

  /** A row's control: its outermost `If(false, inner, real)` replaced by `real`, located by the reader. */
  def control(body: String): Option[String] = {
    val bytes = Base16.decode(body).get
    (0 until body.length / 2).find(p => body.startsWith("950100", p * 2)).flatMap { p =>
      scala.util.Try(sigma.VersionContext.withVersions(3, 3) {
        val r = SigmaSerializer.startReader(bytes, p + 3)
        sigma.serialization.ValueSerializer.deserialize(r)
        val realStart = r.position
        sigma.serialization.ValueSerializer.deserialize(r)
        val realEnd = r.position
        body.take(p * 2) + body.slice(realStart * 2, realEnd * 2) + body.drop(realEnd * 2)
      }).toOption
    }
  }

  /** sigma-rust's set and row name and expression, verbatim; a control carries the row it was derived from. */
  case class Row(set: String, name: String, expr: String, accept: Boolean, control: Boolean, refused: Boolean = false) {
    def treeHex: String = "0b" + vlq(expr.length / 2) + expr
  }

