    Row("control", "recv|updated(Long)|map", "dc0c03100306020401d90101049a72010402", accept = true, control = true))

  private val Rule = "The inner call (in the untaken branch) has only concrete types but does not unify with its " +
    "method's domain, so `specializeFor` returns the method as it is and the call is typed by the TABLE's variable " +
    "(`Coll[IV]` on the JVM); the outer generic call meets that name, and `unifyTypes` unifies `IV` with `IV` only."

  /** `if (true) true else { val v100 = expr; false }`: the expression's PARSE outcome alone. */
  def wrap(expr: String): String = "950101" + "0101" + "d801d664" + expr + "0100"

  /** A parse-only TWIN for every selected row the JVM errors on: true where the JVM parses the expression (it throws
    * only at evaluation), errored where it refuses it at parse. The eval tier grades a parse refusal and an
    * evaluation throw alike, so the bare row cannot tell them apart; the twin can. */
  case class Twin(of: Row) {
    def treeHex: String = { val b = wrap(of.expr); "0b" + vlq(b.length / 2) + b }
    def accept: Boolean = !of.refused
  }
  lazy val Twins: Seq[Twin] = Rows.filter(r => !r.control && !r.accept).map(Twin)

  def extract(): Map[String, Json] = {
    val twinEntries = Twins.map { t =>
      val r = t.of
      val (_, outcome) = EvalCore.evalApplied(t.treeHex, IntInput, activated = 3)
      val said = outcome.fold(e => s"— REFUSED AT PARSE (`${e.take(120)}`)", { case (v, c) => s"→ built, true at cost $c" })
      val why = if (t.accept) "The JVM PARSES the expression and throws only when it is evaluated (the bare row). " +
        "SEPARATING: an implementation that refuses it at parse (its tables naming the variables otherwise) errors here."
        else "The JVM refuses the expression at PARSE. SEPARATING: an implementation that builds it is green on the " +
          "bare row (an evaluation throw grades alike) but returns true here."
      (s"[${r.set}|${r.name}|parse] `${r.name}` inside `if (true) true else { val v = …; false }`, its parse outcome " +
        s"alone, $said. $why", t.treeHex, t.accept, s"parse-${r.set.stripSuffix(".txt")}-${r.name.replaceAll("[^A-Za-z0-9]+", "-").take(54)}")
    }
    val rowEntries = Rows.zipWithIndex.map { case (r, i) =>
      val (_, outcome) = EvalCore.evalApplied(r.treeHex, IntInput, activated = 3)
      val said = outcome.fold(e => s"— ${if (e.contains("ConstraintFailed")) "REFUSED AT PARSE" else "THROWS"} (`${e.take(120)}`)",
        { case (v, c) => s"→ ${v.noSpaces.take(70)} at cost $c" })
      val s =
        if (r.control) s"[control|${r.name}] The outer call and consumer of `${r.name}` over the real value directly " +
          s"(no untaken inner call) $said. CONTROL: the outer call itself evaluates."
        else s"[${r.set}|${r.name}] `${r.name}` (sigma-rust's ${r.set}) $said. $Rule SEPARATING: an implementation " +
          "whose method tables name these variables otherwise answers the other way."
      val name = s"${if (r.control) "control" else r.set.stripSuffix(".txt")}-${r.name.replaceAll("[^A-Za-z0-9]+", "-").take(60)}#$i"
      if (r.accept) SpecExtract.authoredEntryV(Op, s, r.treeHex, name, IntInput, 3, ergoTree = 3)
      else SpecExtract.authoredRejectEntryV(Op, s, r.treeHex, name, IntInput, 3, ergoTree = 3)
    }
    val n = rowEntries.size
    val twins = twinEntries.zipWithIndex.map { case ((s, tree, accept, slug), j) =>
      if (accept) SpecExtract.authoredEntryV(Op, s, tree, s"$slug#${n + j}", IntInput, 3, ergoTree = 3)
      else SpecExtract.authoredRejectEntryV(Op, s, tree, s"$slug#${n + j}", IntInput, 3, ergoTree = 3)
    }
    Map(Op -> SpecExtract.authoredEnvelope(Op, rowEntries ++ twins, Source)
      .mapObject(_.add("blessed_by", Json.fromString(Stamp))))
  }

  def writeVectors(outDir: java.nio.file.Path): Unit =
    SpecExtract.writeStaging("AuthoredEvalUnspecialisedCallNames", extract(), outDir)
}
